<?php
session_start();require __DIR__.'/db.php';require __DIR__.'/helpers.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$reservations=$pdo->query("SELECT r.reservation_id, CONCAT('Reservation #',r.reservation_id,' — ',p.first_name,' ',p.last_name) label FROM reservation r JOIN passenger p ON p.passenger_id=r.passenger_id ORDER BY r.reservation_id DESC")->fetchAll();$r=null;$payments=[];$legs=[];if($id){$s=$pdo->prepare('SELECT r.*,p.first_name,p.second_name,p.last_name,p.email_address,p.phone_number,a.agent_name FROM reservation r JOIN passenger p ON p.passenger_id=r.passenger_id LEFT JOIN booking_agent a ON a.agent_id=r.agent_id WHERE r.reservation_id=?');$s->execute([$id]);$r=$s->fetch();if($r){$s=$pdo->prepare('SELECT p.* FROM reservation_payment rp JOIN payment p ON p.payment_id=rp.payment_id WHERE rp.reservation_id=?');$s->execute([$id]);$payments=$s->fetchAll();$s=$pdo->prepare('SELECT l.*,fs.airline_code,oa.airport_name origin_name,da.airport_name destination_name FROM reservation_leg rl JOIN flight_leg l ON l.leg_id=rl.leg_id JOIN flight_schedule fs ON fs.flight_number=l.flight_number JOIN airport oa ON oa.airport_code=l.origin_airport_code JOIN airport da ON da.airport_code=l.destination_airport_code WHERE rl.reservation_id=?');$s->execute([$id]);$legs=$s->fetchAll();}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reservation Details · HarborWing</title><link rel="stylesheet" href="assets/style.css"></head><body><header><a class="brand" href="index.php">✈ HarborWing Air</a><span>Reservation Management</span></header><div class="layout"><aside><h3>Modules</h3><a class="navlink" href="index.php">Dashboard</a><a class="navlink" href="relations.php">Reservation Links</a><a class="navlink active" href="reservation_details.php">Reservation Details</a></aside><main><p class="eyebrow">FULL RESERVATION VIEW</p><h1>Reservation Details</h1><section class="panel"><form method="get" class="inlineform"><label>Choose reservation<select name="id" required><option value="">Choose...</option><?php foreach($reservations as $x):?><option value="<?=e($x['reservation_id'])?>" <?=($id===(int)$x['reservation_id'])?'selected':''?>><?=e($x['label'])?></option><?php endforeach;?></select></label><button class="button">View reservation</button></form></section><?php if($id && !$r):?><div class="notice error">Reservation not found.</div><?php elseif($r):?><section class="panel"><h2>Reservation #<?=e($r['reservation_id'])?></h2><div class="detailsgrid"><?php foreach(['Passenger'=>trim($r['first_name'].' '.$r['second_name'].' '.$r['last_name']),'Email'=>$r['email_address'],'Phone'=>$r['phone_number'],'Booking agent'=>$r['agent_name'],'Status'=>$r['reservation_status_code'],'Ticket type'=>$r['ticket_type_code'],'Travel class'=>$r['travel_class_code'],'Created (UTC)'=>$r['created_at_utc'],'Party size'=>$r['party_size']] as $k=>$v):?><div><small><?=e($k)?></small><strong><?=e($v?:'—')?></strong></div><?php endforeach;?></div></section><section class="panel"><h2>Payments</h2><div class="tablewrap"><table><thead><tr><th>ID</th><th>Status</th><th>Date (UTC)</th><th>Amount</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=e($p['payment_id'])?></td><td><?=e($p['payment_status_code'])?></td><td><?=e($p['payment_date_utc'])?></td><td><?=e($p['payment_amount'])?></td></tr><?php endforeach;if(!$payments):?><tr><td colspan="4">No linked payments.</td></tr><?php endif;?></tbody></table></div></section><section class="panel"><h2>Flight legs</h2><div class="tablewrap"><table><thead><tr><th>Leg ID</th><th>Flight</th><th>Airline</th><th>Route</th><th>Actual departure</th><th>Actual arrival</th></tr></thead><tbody><?php foreach($legs as $l):?><tr><td><?=e($l['leg_id'])?></td><td><?=e($l['flight_number'])?></td><td><?=e($l['airline_code'])?></td><td><?=e($l['origin_name'])?> → <?=e($l['destination_name'])?></td><td><?=e($l['actual_departure_utc']?:'—')?></td><td><?=e($l['actual_arrival_utc']?:'—')?></td></tr><?php endforeach;if(!$legs):?><tr><td colspan="6">No linked flight legs.</td></tr><?php endif;?></tbody></table></div></section><p><a class="button" href="relations.php">Manage reservation links</a></p><?php endif;?></main></div></body></html>
